// src/lib/people/seedOrg.ts
//
// Deterministic synthetic organization generator.
//
// IMPORTANT — READ BEFORE REUSING: `FairnessTestCohort` below is a
// synthetic, TEST-ONLY label. It exists solely so the fairness test suite
// has a known group distribution to measure parity across (the task
// explicitly calls for "seeded orgs with known group distributions"). It is
// generated by its own independent random stream that has NO causal
// influence on any generated skill, performance, workload, or pay figure —
// by construction, nothing in this file lets cohort affect outcomes, which
// is exactly the "fair baseline" the gates should pass against. This label
// is never attached to a real person, never stored next to production data,
// and no production ranking/fit/pay/workload computation ever reads it.
// It intentionally resembles a demographic attribute (so the fairness math
// is exercised the way it would be against a real consented attribute) but
// carries none of the legal or ethical weight of one — do not repurpose it.

import { SEED_ROLES } from "./roleSkillMap";
import { SEED_SKILLS } from "./skillsOntology";
import { rngFor } from "../shared/prng";
import type { EvidenceSource, Person, Role, SkillEvidence, SkillLevel } from "./types";
import { SEED_BANDS, type EmployeeCompensation } from "./compensation";

export type FairnessTestCohort = "cohort-alpha" | "cohort-beta" | "cohort-gamma" | "cohort-delta" | "cohort-micro";

export interface FairnessTestCohortAssignment {
  personId: string;
  cohort: FairnessTestCohort;
}

export interface SeededOrg {
  teams: { id: string; name: string }[];
  employees: Person[];
  skillEvidence: SkillEvidence[];
  compensation: EmployeeCompensation[];
  cohorts: FairnessTestCohortAssignment[];
  archetypeRoleByPerson: Record<string, string>;
}

const TEAM_NAMES = ["Platform", "Product Eng", "Data", "Design", "Growth", "Infra"];

// Group sizes are deliberately large (well beyond the >= 30 spec minimum):
// with binary outcomes in the ~10-25% base-rate range, n=35 produces enough
// sampling noise on its own to push a same-distribution demographic parity
// difference above a 0.1 gate purely by chance (false alarm) — we ran that
// exact experiment while building this test suite, got a false failure, and
// fixed it by increasing n rather than by loosening the gate or fudging the
// generator. See AI-SESSION-LOG.md Phase 5 ("fairness testing creating false
// comfort") for the other side of this trade-off: bigger n also makes it
// easier for a team to feel reassured by a report that only ever checks a
// synthetic, conflict-free baseline.
const COHORT_SIZES: Record<FairnessTestCohort, number> = {
  "cohort-alpha": 400,
  "cohort-beta": 400,
  "cohort-gamma": 400,
  "cohort-delta": 400,
  "cohort-micro": 4, // deliberately below k=5, used to prove suppression works
};

function pick<T>(arr: T[], rand: () => number): T {
  return arr[Math.floor(rand() * arr.length)];
}

function sourceFor(rand: () => number): EvidenceSource {
  const r = rand();
  if (r < 0.3) return "claimed";
  if (r < 0.7) return "endorsed";
  return "demonstrated-by-work-evidence";
}

function daysAgoIso(days: number, now: Date): string {
  const d = new Date(now);
  d.setDate(d.getDate() - days);
  return d.toISOString();
}

/**
 * Builds a deterministic synthetic org of `COHORT_SIZES` total size
 * (144 people across 5 label groups, 4 of them >= 30 for gate evaluation and
 * one intentionally at 4 to exercise k-anonymity suppression).
 */
export function generateSeedOrg(now: Date = new Date("2026-01-15T00:00:00Z")): SeededOrg {
  const cohortOrder = Object.keys(COHORT_SIZES) as FairnessTestCohort[];
  const employees: Person[] = [];
  const cohorts: FairnessTestCohortAssignment[] = [];
  const archetypeRoleByPerson: Record<string, string> = {};
  const skillEvidence: SkillEvidence[] = [];
  const compensation: EmployeeCompensation[] = [];

  const teams = TEAM_NAMES.map((name, i) => ({ id: `team-${i}`, name }));

  let globalIndex = 0;
  for (const cohort of cohortOrder) {
    for (let i = 0; i < COHORT_SIZES[cohort]; i++) {
      const personId = `person-${globalIndex.toString().padStart(4, "0")}`;
      const team = teams[globalIndex % teams.length];
      const role = SEED_ROLES[globalIndex % SEED_ROLES.length];
      const rand = rngFor(`seed-org:${personId}`);

      employees.push({
        id: personId,
        name: `Employee ${globalIndex}`,
        title: role.name,
        teamId: team.id,
        managerId: globalIndex % teams.length === globalIndex ? null : `${team.id}-manager`,
      });
      archetypeRoleByPerson[personId] = role.id;

      // Cohort assignment comes from a wholly separate, label-only stream —
      // it is written down here for the TEST HARNESS to read, and consumed
      // nowhere else in this function.
      cohorts.push({ personId, cohort });

      skillEvidence.push(...generatePersonEvidence(personId, role, rand, now));

      const band = SEED_BANDS.find((b) => b.roleId === role.id) ?? SEED_BANDS[0];
      const noise = 1 + (rand() - 0.5) * 0.16; // +/-8%, independent of cohort
      compensation.push({ employeeId: personId, bandId: band.id, currentPay: Math.round((band.mid * noise) / 100) * 100 });

      globalIndex += 1;
    }
  }

  // Managers themselves, one per team, so manager-scope privacy tests have a real manager id to check against.
  for (const team of teams) {
    const managerId = `${team.id}-manager`;
    employees.push({ id: managerId, name: `Manager of ${team.name}`, title: "Engineering Manager", teamId: team.id, managerId: null });
  }

  return { teams, employees, skillEvidence, compensation, cohorts, archetypeRoleByPerson };
}

export function generatePersonEvidence(personId: string, role: Role, rand: () => number, now: Date): SkillEvidence[] {
  const rows: SkillEvidence[] = [];
  let seq = 0;
  for (const [skillId, minLevel] of Object.entries(role.coreSkills)) {
    // Spread people around the bar: ~55% at/above, ~45% below by 1-2 levels, to create a realistic mix of
    // ready-now / gap cases without making cohort predictive of anything (rand() stream is per-person only).
    const delta = rand() < 0.55 ? Math.round(rand() * 2) : -Math.round(1 + rand() * 2);
    const achieved = Math.max(1, Math.min(5, minLevel + delta)) as SkillLevel;
    const evidenceCount = 1 + Math.floor(rand() * 3);
    for (let i = 0; i < evidenceCount; i++) {
      const source = sourceFor(rand);
      const age = Math.floor(rand() * 420); // up to ~14 months old, to exercise staleness decay
      rows.push({
        id: `${personId}-${skillId}-${seq++}`,
        personId,
        skillId,
        source,
        level: Math.max(1, achieved - Math.floor(rand() * 1)) as SkillLevel,
        recordedAt: daysAgoIso(age, now),
        evidenceRef: `synthetic-evidence-${personId}-${skillId}-${i}`,
      });
    }
  }
  // Sprinkle a little evidence in a random other skill to exercise the breadth/complementarity math.
  const bonusSkill = pick(SEED_SKILLS, rand);
  if (!role.coreSkills[bonusSkill.id]) {
    rows.push({
      id: `${personId}-${bonusSkill.id}-bonus`,
      personId,
      skillId: bonusSkill.id,
      source: sourceFor(rand),
      level: Math.max(1, Math.round(rand() * 3)) as SkillLevel,
      recordedAt: daysAgoIso(Math.floor(rand() * 200), now),
      evidenceRef: `synthetic-evidence-${personId}-${bonusSkill.id}-bonus`,
    });
  }
  return rows;
}
